function partition(s) {
  const n = s.length;

  // isPal[i][j]: does s[i..j] read the same both ways?
  const isPal = Array.from({ length: n }, () => new Array(n).fill(false));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      // Ends match, and the inside is already known to be a palindrome.
      isPal[i][j] = s[i] === s[j] && (j - i < 2 || isPal[i + 1][j - 1]);
    }
  }

  const answers = [];
  const current = [];

  function solve(start) {
    if (start === n) {
      answers.push([...current]);
      return;
    }

    for (let end = start; end < n; end++) {
      if (!isPal[start][end]) continue;      // the prune, now a lookup

      current.push(s.slice(start, end + 1));
      solve(end + 1);
      current.pop();
    }
  }

  solve(0);
  return answers;
}

