def partition(s):
    n = len(s)

    # is_pal[i][j]: does s[i..j] read the same both ways?
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            # Ends match, and the inside is already known to be a palindrome.
            is_pal[i][j] = s[i] == s[j] and (j - i < 2 or is_pal[i + 1][j - 1])

    answers, current = [], []

    def solve(start):
        if start == n:
            answers.append(current[:])
            return

        for end in range(start, n):
            if not is_pal[start][end]:
                continue                      # the prune, now a lookup

            current.append(s[start:end + 1])
            solve(end + 1)
            current.pop()

    solve(0)
    return answers
